const tableMap={students:['one_students','students-form'],guardians:['one_guardians','guardians-form'],companies:['one_companies','companies-form'],products:['one_products','products-form'],enrollments:['one_enrollments','enrollments-form'],contracts:['one_contracts','contracts-form'],service:['one_service_history','service-form'],tasks:['one_tasks','tasks-form'],documents:['one_documents','documents-form']};
