async function saveDocument(event){event.preventDefault();const p=formPayload(event.currentTarget);if(p.entity_type==='geral')p.entity_id=null;try{await one.save('one_documents',p,state.editing.documents);toast(state.editing.documents?'Documento atualizado.':'Documento registrado.');resetForm('documents');await refreshAll()}catch(e){toast(e.message,'error')}}
async function generateReceivables(id){try{const count=await one.generateContractReceivables(id);toast(count?`${count} lançamento(s) criado(s).`:'As parcelas desse contrato já estavam geradas.');await refreshAll();state.desktop.open('finance')}catch(e){toast(e.message,'error')}}
function printContractById(id){const c=state.contracts.find(x=>x.id===id);if(!c)return;const student=c.student?.full_name||'—',contractor=c.guardian?.full_name||c.company?.trade_name||c.company?.legal_name||student,product=c.product?.name||'—',w=window.open('','_blank','width=900,height=800');if(!w)return toast('O navegador bloqueou a janela de impressão.','warning');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Contrato ${escapeHTML(c.contract_number)}</title><style>body{font:15px Arial;color:#222;max-width:820px;margin:40px auto;line-height:1.55}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin:20px 0}td{padding:9px;border:1px solid #ddd}.brand{font-weight:900;color:#6d28d9;letter-spacing:2px}.note{background:#f5f3ff;padding:14px;border-radius:8px}.sign{margin-top:70px;display:grid;grid-template-columns:1fr 1fr;gap:50px}.line{border-top:1px solid #333;padding-top:8px;text-align:center}</style></head><body><div class="brand">EVOLUA ONE</div><h1>Ficha Contratual nº ${escapeHTML(c.contract_number)}</h1><p>Documento de conferência gerado pelo sistema. O modelo jurídico oficial da escola pode ser anexado/substituído na Central de Documentos.</p><table><tr><td><b>Aluno</b></td><td>${escapeHTML(student)}</td></tr><tr><td><b>Contratante</b></td><td>${escapeHTML(contractor)}</td></tr><tr><td><b>Produto / plano</b></td><td>${escapeHTML(product)}</td></tr><tr><td><b>Data</b></td><td>${fmtDate(c.contract_date)}</td></tr><tr><td><b>Início</b></td><td>${fmtDate(c.start_date)}</td></tr><tr><td><b>Término</b></td><td>${fmtDate(c.end_date)}</td></tr><tr><td><b>Valor contratado</b></td><td>${money(c.contract_value)}</td></tr><tr><td><b>Matrícula</b></td><td>${money(c.enrollment_fee)}</td></tr><tr><td><b>Parcelas</b></td><td>${c.installments} × ${money(c.installment_value)}</td></tr><tr><td><b>1º vencimento</b></td><td>${fmtDate(c.first_due_date)}</td></tr><tr><td><b>Status</b></td><td>${contractStatus[c.status]||c.status}</td></tr></table><div class="note"><b>Observações</b><br>${escapeHTML(c.notes||'Sem observações.')}</div><div class="sign"><div class="line">Contratante</div><div class="line">Evolua</div></div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function resetForm(kind){state.editing[kind]=null;const form=$(`#${kind}-form`);form?.reset();const titles={students:'Novo aluno',guardians:'Novo responsável',companies:'Nova empresa',products:'Novo produto ou plano',enrollments:'Nova matrícula',contracts:'Novo contrato',service:'Novo atendimento',tasks:'Nova tarefa',documents:'Registrar documento'},title=$(`#${kind}-form-title`);if(title)title.textContent=titles[kind];if(kind==='enrollments'){$('#enrollment-number').value=nextEnrollmentNumber();$('#enrollment-date').value=todayISO()}if(kind==='contracts'){$('#contract-number').value=nextContractNumber();$('#contract-date').value=todayISO();$('#contract-student-id').value='';$('#contract-product-id').value=''}if(kind==='service')updateServiceEntitySelect();if(kind==='documents')updateDocumentEntitySelect()}
function csvDownload(filename,rows){const esc=v=>`"${String(v??'').replaceAll('"','""')}"`,csv=rows.map(r=>r.map(esc).join(';')).join('\r\n'),blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});downloadBlob(blob,filename)}
function downloadBlob(blob,filename){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
async function backupNow(){try{const data=await one.backupData(),recordCount=Object.values(data).reduce((n,rows)=>n+rows.length,0),now=new Date(),stamp=`${now.toISOString().slice(0,10)}_${String(now.getHours()).padStart(2,'0')}${String(now.getMinutes()).padStart(2,'0')}`,fileName=`EvoluaOne_Backup_${stamp}.json`,packageData={manifest:{app:'Evolua One',version:VERSION,generated_at:now.toISOString(),workspace_id:state.workspaceId,generated_by:state.user.email,record_count:recordCount},data},blob=new Blob([JSON.stringify(packageData,null,2)],{type:'application/json'});let destination='download';if(window.showSaveFilePicker){try{const handle=await window.showSaveFilePicker({suggestedName:fileName,types:[{description:'Backup Evolua One',accept:{'application/json':['.json']}}]}),writer=await handle.createWritable();await writer.write(blob);await writer.close();destination='Windows / pasta escolhida'}catch(e){if(e.name==='AbortError')return;throw e}}else downloadBlob(blob,fileName);await one.save('one_backup_log',{file_name:fileName,destination,record_count:recordCount,app_version:VERSION});toast(`Backup concluído: ${recordCount} registros.`);await refreshAll()}catch(e){toast(`Falha no backup: ${e.message}`,'error')}}
function exportSummaryCSV(){csvDownload(`EvoluaOne_Resumo_${todayISO()}.csv`,[['Indicador','Valor'],['Alunos',state.students.length],['Responsáveis',state.guardians.length],['Empresas',state.companies.length],['Produtos',state.products.length],['Matrículas',state.enrollments.length],['Contratos',state.contracts.length],['Contas a receber',state.receivables.length],['Recebimentos',state.receipts.length],['Contas a pagar',state.payables.length],['Tarefas',state.tasks.length],['Documentos',state.documents.length]])}
function exportReportCSV(){csvDownload(`EvoluaOne_Relatorio_${todayISO()}.csv`,[['Área','Indicador','Valor'],['Secretaria','Alunos cadastrados',state.students.length],['Secretaria','Matrículas ativas',state.enrollments.filter(x=>x.status==='ativa').length],['Contratos','Ativos',state.contracts.filter(x=>x.status==='ativo').length],['Financeiro','Recebido total',sum(state.receipts.filter(x=>!x.reversed),x=>x.amount)],['Financeiro','Despesas pagas',sum(state.payablePayments.filter(x=>!x.reversed),x=>x.amount)],['Financeiro','Inadimplência',sum(state.receivables.filter(isOverdue),r=>Math.max(0,totalDue(r)-paidForReceivable(r.id)))],['Agenda','Pendentes',state.tasks.filter(x=>['pendente','em_andamento'].includes(x.status)).length]])}
function printReport(){const content=$('[data-window="reports"] .window-body').innerHTML,w=window.open('','_blank','width=1000,height=800');if(!w)return toast('O navegador bloqueou a impressão.','warning');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Relatório Evolua One</title><style>body{font:14px Arial;padding:30px;color:#222}.metric-grid,.report-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.metric-card,.report-card{border:1px solid #ddd;padding:15px;border-radius:10px}.metric-card small,.metric-card strong,.metric-card em{display:block}.metric-card strong{font-size:20px}.report-line{display:flex;justify-content:space-between;padding:7px;border-bottom:1px solid #eee}.panel-head .form-actions{display:none}</style></head><body><h1>Evolua One • Relatório Executivo</h1><p>Gerado em ${new Date().toLocaleString('pt-BR')}</p>${content}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function bindFormControls(){$('#students-form').addEventListener('submit',saveStudent);$('#guardians-form').addEventListener('submit',saveGuardian);$('#companies-form').addEventListener('submit',saveCompany);$('#products-form').addEventListener('submit',saveProduct);$('#enrollments-form').addEventListener('submit',saveEnrollment);$('#contracts-form').addEventListener('submit',saveContract);$('#service-form').addEventListener('submit',saveService);$('#receivable-form').addEventListener('submit',saveReceivable);$('#payable-form').addEventListener('submit',savePayable);$('#financial-account-form').addEventListener('submit',saveFinancialAccount);$('#tasks-form').addEventListener('submit',saveTask);$('#documents-form').addEventListener('submit',saveDocument);$('#student-save-contract').addEventListener('click',()=>{$('#students-form').dataset.advance='enrollment';$('#students-form').requestSubmit()});$('#enrollment-save-contract').addEventListener('click',()=>{$('#enrollments-form').dataset.advance='contract';$('#enrollments-form').requestSubmit()});$$('[data-reset-form]').forEach(b=>b.addEventListener('click',()=>resetForm(b.dataset.resetForm)));$$('[data-mask="cpf"]').forEach(i=>i.addEventListener('input',()=>i.value=formatCPF(i.value)));$$('[data-mask="cnpj"]').forEach(i=>i.addEventListener('input',()=>i.value=formatCNPJ(i.value)));$$('[data-mask="cep"]').forEach(i=>i.addEventListener('input',()=>i.value=formatCEP(i.value)));$$('[data-mask="phone"]').forEach(i=>i.addEventListener('input',()=>i.value=formatPhone(i.value)));$('#student-cep').addEventListener('change',()=>fetchCEP($('#student-cep'),'#student-city','#student-state'));$('#guardian-cep').addEventListener('change',()=>fetchCEP($('#guardian-cep'),'#guardian-city','#guardian-state'));$('#company-cep').addEventListener('change',()=>fetchCEP($('#company-cep'),'#company-city','#company-state'));$('#contract-enrollment-id').addEventListener('change',()=>syncContractEnrollment($('#contract-enrollment-id').value));$('#contract-print-button').addEventListener('click',()=>{if(state.editing.contracts)printContractById(state.editing.contracts);else toast('Salve o contrato primeiro. Depois use o botão Ficha na lista.','warning')});$('#service-entity-type').addEventListener('change',updateServiceEntitySelect);$('#document-entity-type').addEventListener('change',updateDocumentEntitySelect);$('#finance-refresh').addEventListener('click',async()=>{await refreshAll();toast('Financeiro atualizado.')});$('#member-add-form').addEventListener('submit',async e=>{e.preventDefault();const p=formPayload(e.currentTarget);try{await one.addExistingMember(p.email,p.role);toast('Usuário vinculado ao Evolua One.');e.currentTarget.reset();await refreshAll()}catch(err){toast(err.message,'error')}});$('#backup-now').addEventListener('click',backupNow);$('#backup-export-csv').addEventListener('click',exportSummaryCSV);$('#reports-export-csv').addEventListener('click',exportReportCSV);$('#reports-print').addEventListener('click',printReport);$$('[data-record-tab]').forEach(b=>b.addEventListener('click',()=>{state.recordTab=b.dataset.recordTab;$$('[data-record-tab]').forEach(x=>x.classList.toggle('active',x===b));renderRecord()}))}
function bindDesktop(){const desktop=new DesktopManager({desktop:$('#desktop-canvas'),taskbarApps:$('#taskbar-apps'),startMenu:$('#start-menu')});state.desktop=desktop;[['secretaria','Secretaria','🏫'],['students','Alunos','👨‍🎓'],['record','Prontuário','🧭'],['guardians','Responsáveis','👨‍👩‍👧'],['companies','Empresas','🏢'],['products','Produtos e Planos','📦'],['enrollments','Matrículas','✅'],['contracts','Contratos','📄'],['service','Histórico de Atendimento','💬'],['commercial','Comercial','🎯'],['finance','Financeiro','💰'],['agenda','Agenda e Tarefas','🗓️'],['documents','Documentos','🗃️'],['reports','Relatórios','📊'],['admin','Administração','⚙️']].forEach(([id,title,icon])=>desktop.register(id,{title,icon}));$$('[data-open-window]').forEach(b=>b.addEventListener('click',()=>desktop.open(b.dataset.openWindow)));$('#start-button').addEventListener('click',e=>{e.stopPropagation();$('#start-menu').classList.toggle('hidden')});document.addEventListener('click',e=>{if(!e.target.closest('#start-menu')&&!e.target.closest('#start-button'))$('#start-menu').classList.add('hidden')});$('#commercial-frame').src=CRM_URL;$('#open-crm-new-tab').href=CRM_URL}
function bindClock(){const tick=()=>{const n=new Date();$('#clock-time').textContent=n.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});$('#clock-date').textContent=n.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'})};tick();setInterval(tick,30000)}
async function init(){document.title=APP_NAME;bindDesktop();bindFormControls();bindClock();['enrollments','contracts','service','tasks','documents'].forEach(resetForm);$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('#login-button');b.disabled=true;b.textContent='Entrando...';const{data,error}=await supabase.auth.signInWithPassword({email:$('#login-email').value.trim(),password:$('#login-password').value});b.disabled=false;b.textContent='Entrar no Evolua One';if(error)return toast('E-mail ou senha inválidos.','error');if(data.user)await enterApp(data.user)});$('#logout-button').addEventListener('click',async()=>{await supabase.auth.signOut();showLogin()});$('#refresh-button').addEventListener('click',async()=>{try{await refreshAll();toast('Dados atualizados.')}catch(e){toast(e.message,'error')}});const{data:{session}}=await supabase.auth.getSession();if(session?.user)await enterApp(session.user);else showLogin();supabase.auth.onAuthStateChange(async(event,s)=>{if(event==='SIGNED_OUT')showLogin();if(event==='SIGNED_IN'&&s?.user&&state.user?.id!==s.user.id)await enterApp(s.user)})}
function renderEnrollments(){if(!$('#enrollments-list'))return;$('#enrollments-list').innerHTML=entityTable({table:'enrollments',rows:state.enrollments,columns:[{label:'Matrícula',render:r=>`<div><strong>${escapeHTML(r.enrollment_number)}</strong><small class="block">${fmtDate(r.enrollment_date)}</small></div>`},{label:'Aluno',render:r=>escapeHTML(r.student?.full_name||'—')},{label:'Produto',render:r=>escapeHTML(r.product?.name||'—')},{label:'Situação',render:r=>`<span class="status-pill ${r.status}">${enrollmentStatus[r.status]||r.status}</span>`}],extraActions:'<button class="mini-btn accent" data-enrollment-record="{id}">Prontuário</button><button class="mini-btn" data-enrollment-contract="{id}">Contrato</button>'});bindEntityActions('enrollments');$$('[data-enrollment-record]').forEach(b=>b.onclick=()=>{const e=state.enrollments.find(x=>x.id===b.dataset.enrollmentRecord);if(e)openRecord(e.student_id)});$$('[data-enrollment-contract]').forEach(b=>b.onclick=()=>openContractForEnrollment(b.dataset.enrollmentContract))}
async function saveEnrollment(event){event.preventDefault();const form=event.currentTarget,p=formPayload(form);if(!p.enrollment_number)p.enrollment_number=nextEnrollmentNumber();if(!p.student_id||!p.product_id)return toast('Selecione aluno e produto.','warning');try{const saved=await one.save('one_enrollments',p,state.editing.enrollments);const advance=form.dataset.advance==='contract';toast(state.editing.enrollments?'Matrícula atualizada.':'Matrícula criada.');resetForm('enrollments');await refreshAll();if(advance)openContractForEnrollment(saved.id)}catch(e){toast(e.message,'error')}finally{delete form.dataset.advance}}
function syncContractEnrollment(id){const e=state.enrollments.find(x=>x.id===id);if(!e)return;$('#contract-enrollment-id').value=e.id;$('#contract-student-id').value=e.student_id||'';$('#contract-product-id').value=e.product_id||'';$('#contract-company-id').value=e.company_id||'';const p=e.product;if(p){$('#contract-value').value=Number(p.list_price||0).toFixed(2);$('#contract-enrollment-fee').value=Number(p.enrollment_fee||0).toFixed(2);$('#contract-installments').value=p.max_installments||1;const n=Number(p.max_installments||1);$('#contract-installment-value').value=(Number(p.list_price||0)/Math.max(n,1)).toFixed(2)}const form=$('#contracts-form');if(e.start_date&&form.elements.namedItem('start_date'))form.elements.namedItem('start_date').value=e.start_date;if(e.end_date&&form.elements.namedItem('end_date'))form.elements.namedItem('end_date').value=e.end_date;if(!$('#contract-first-due-date').value)$('#contract-first-due-date').value=e.start_date||todayISO()}
function openContractForEnrollment(id){resetForm('contracts');state.desktop.open('contracts');setTimeout(()=>syncContractEnrollment(id),0)}
function openRecord(studentId){state.activeRecordStudentId=studentId;state.recordTab='summary';$$('[data-record-tab]').forEach(b=>b.classList.toggle('active',b.dataset.recordTab==='summary'));renderRecord();state.desktop.open('record')}
function recordStudent(){return state.students.find(x=>x.id===state.activeRecordStudentId)}
function renderRecord(){const s=recordStudent(),header=$('#record-header'),content=$('#record-content');if(!s||!header||!content)return;const enrollments=state.enrollments.filter(x=>x.student_id===s.id),contracts=state.contracts.filter(x=>x.student_id===s.id),receivables=state.receivables.filter(x=>x.student_id===s.id),services=state.serviceHistory.filter(x=>x.student_id===s.id),links=state.studentGuardians.filter(x=>x.student_id===s.id),docs=state.documents.filter(x=>x.entity_type==='student'&&x.entity_id===s.id),active=enrollments.filter(x=>x.status==='ativa').length;header.innerHTML=`<div class="record-person">${s.photo_url?`<img src="${escapeHTML(s.photo_url)}">`:`<span class="record-avatar">${escapeHTML((s.full_name||'?')[0])}</span>`}<div><p class="eyebrow">PRONTUÁRIO ÚNICO</p><h2>${escapeHTML(s.full_name)}</h2><p>${s.cpf?formatCPF(s.cpf):'CPF não informado'} • ${escapeHTML(s.whatsapp||s.phone||'Sem telefone')}</p></div></div><div class="record-actions"><span class="status-pill ${active?'ativo':'inativo'}">${active?`${active} matrícula(s) ativa(s)`:'Sem matrícula ativa'}</span><button class="btn secondary small" data-record-new-enrollment>+ Matrícula</button><button class="btn secondary small" data-record-service>+ Atendimento</button></div>`;header.querySelector('[data-record-new-enrollment]').onclick=()=>{resetForm('enrollments');state.desktop.open('enrollments');setTimeout(()=>$('#enrollment-student-id').value=s.id,0)};header.querySelector('[data-record-service]').onclick=()=>{resetForm('service');state.desktop.open('service');setTimeout(()=>{$('#service-entity-type').value='student';updateServiceEntitySelect();$('#service-entity-id').value=s.id},0)};const tab=state.recordTab;if(tab==='summary'){content.innerHTML=renderRecordSummary(s,enrollments,contracts,receivables,services,links,docs)}else if(tab==='enrollments'){content.innerHTML=renderRecordEnrollments(enrollments)}else if(tab==='contracts'){content.innerHTML=renderRecordContracts(contracts)}else if(tab==='finance'){content.innerHTML=renderRecordFinance(receivables)}else if(tab==='service'){content.innerHTML=renderRecordServices(services)}else if(tab==='guardians'){content.innerHTML=renderRecordGuardians(s,links)}else if(tab==='documents'){content.innerHTML=renderRecordDocuments(docs)}else content.innerHTML=renderRecordTimeline(s,enrollments,contracts,receivables,services,docs);bindRecordActions()}
function renderRecordSummary(s,enrollments,contracts,receivables,services,links,docs){const open=receivables.filter(x=>['aberto','parcial'].includes(x.status)),debt=sum(open,r=>Math.max(0,totalDue(r)-paidForReceivable(r.id)));return`<div class="record-summary-grid"><article><small>Matrículas</small><strong>${enrollments.length}</strong><em>${enrollments.filter(x=>x.status==='ativa').length} ativas</em></article><article><small>Contratos</small><strong>${contracts.length}</strong><em>${contracts.filter(x=>x.status==='ativo').length} ativos</em></article><article><small>Em aberto</small><strong>${money(debt)}</strong><em>${open.length} parcelas</em></article><article><small>Atendimentos</small><strong>${services.length}</strong><em>${links.length} responsáveis vinculados</em></article></div><div class="record-two-cols"><section class="report-card"><h3>Dados principais</h3><div class="report-line"><span>Nascimento</span><b>${fmtDate(s.birth_date)}</b></div><div class="report-line"><span>E-mail</span><b>${escapeHTML(s.email||'—')}</b></div><div class="report-line"><span>Endereço</span><b>${escapeHTML([s.street,s.number,s.neighborhood,s.city,s.state].filter(Boolean).join(', ')||'—')}</b></div></section><section class="report-card"><h3>Últimos movimentos</h3>${renderRecordTimeline(s,enrollments,contracts,receivables,services,docs,true)}</section></div>`}
function renderRecordEnrollments(rows){return rows.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Matrícula</th><th>Produto</th><th>Data</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.enrollment_number)}</td><td>${escapeHTML(r.product?.name||'—')}</td><td>${fmtDate(r.enrollment_date)}</td><td><span class="status-pill ${r.status}">${enrollmentStatus[r.status]||r.status}</span></td><td><button class="mini-btn" data-record-contract="${r.id}">Abrir contrato</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Nenhuma matrícula.</div>'}
function renderRecordContracts(rows){return rows.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Contrato</th><th>Produto</th><th>Valor</th><th>Status</th><th>Ação</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.contract_number)}</td><td>${escapeHTML(r.product?.name||'—')}</td><td>${money(Number(r.contract_value||0)+Number(r.enrollment_fee||0))}</td><td><span class="status-pill ${r.status}">${contractStatus[r.status]||r.status}</span></td><td><button class="mini-btn" data-record-print="${r.id}">Ficha</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Nenhum contrato.</div>'}
function renderRecordFinance(rows){return rows.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Descrição</th><th>Vencimento</th><th>Total</th><th>Pago</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.description)}</td><td>${fmtDate(r.due_date)}</td><td>${money(totalDue(r))}</td><td>${money(paidForReceivable(r.id))}</td><td><span class="status-pill ${isOverdue(r)?'urgente':r.status}">${isOverdue(r)?'Vencida':r.status}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">Nenhum lançamento financeiro.</div>'}
function renderRecordServices(rows){return rows.length?rows.map(r=>`<div class="timeline-item"><span>💬</span><div><strong>${escapeHTML(r.category||'Atendimento')}</strong><small>${fmtDateTime(r.occurred_at)} • ${escapeHTML(r.channel||'')}</small><p>${escapeHTML(r.summary)}</p></div></div>`).join(''):'<div class="empty-state">Nenhum atendimento registrado.</div>'}
function renderRecordGuardians(s,links){const available=state.guardians.filter(g=>!links.some(l=>l.guardian_id===g.id)&&g.active);return`<div class="record-link-box"><h3>Vincular responsável</h3><div class="inline-form"><select id="record-guardian-select">${options(available,'id',x=>x.full_name,'Selecione um responsável')}</select><select id="record-guardian-relationship"><option value="Mãe">Mãe</option><option value="Pai">Pai</option><option value="Tutor">Tutor</option><option value="Outro">Outro</option></select><button class="btn primary" data-record-link-guardian>Vincular</button></div></div>${links.length?links.map(l=>`<div class="guardian-link-row"><div><strong>${escapeHTML(l.guardian?.full_name||'Responsável')}</strong><small>${escapeHTML(l.relationship||'')} ${l.is_financial?'• Financeiro':''} ${l.is_legal?'• Legal':''}</small></div><div class="row-actions"><button class="mini-btn" data-record-toggle-financial="${l.id}">${l.is_financial?'✓ Financeiro':'Marcar financeiro'}</button><button class="mini-btn danger" data-record-unlink-guardian="${l.id}">Desvincular</button></div></div>`).join(''):'<div class="empty-state">Nenhum responsável vinculado.</div>'}` }
function renderRecordDocuments(rows){return rows.length?rows.map(d=>`<div class="document-row"><div><strong>${escapeHTML(d.title)}</strong><small>${escapeHTML(d.document_type||'Documento')} • ${fmtDateTime(d.created_at)}</small></div>${d.drive_url?`<a class="mini-btn" href="${escapeHTML(d.drive_url)}" target="_blank">Abrir Drive</a>`:''}</div>`).join(''):'<div class="empty-state">Nenhum documento diretamente vinculado ao aluno.</div>'}
function renderRecordTimeline(s,enrollments,contracts,receivables,services,docs,compact=false){const events=[];enrollments.forEach(x=>events.push({date:x.created_at,icon:'✅',title:`Matrícula ${x.enrollment_number}`,detail:`${x.product?.name||'Produto'} • ${enrollmentStatus[x.status]||x.status}`}));contracts.forEach(x=>events.push({date:x.created_at,icon:'📄',title:`Contrato ${x.contract_number}`,detail:`${contractStatus[x.status]||x.status} • ${money(Number(x.contract_value||0)+Number(x.enrollment_fee||0))}`}));services.forEach(x=>events.push({date:x.occurred_at,icon:'💬',title:x.category||'Atendimento',detail:x.summary}));receivables.forEach(r=>state.receipts.filter(x=>x.receivable_id===r.id&&!x.reversed).forEach(x=>events.push({date:x.paid_at,icon:'💰',title:`Recebimento ${money(x.amount)}`,detail:r.description})));docs.forEach(x=>events.push({date:x.created_at,icon:'🗃️',title:x.title,detail:x.document_type||'Documento'}));events.sort((a,b)=>new Date(b.date)-new Date(a.date));const slice=compact?events.slice(0,5):events;return slice.length?slice.map(e=>`<div class="timeline-item ${compact?'compact':''}"><span>${e.icon}</span><div><strong>${escapeHTML(e.title)}</strong><small>${fmtDateTime(e.date)}</small><p>${escapeHTML(e.detail||'')}</p></div></div>`).join(''):'<div class="empty-state">A jornada deste aluno começa aqui.</div>'}
function bindRecordActions(){$$('[data-record-contract]').forEach(b=>b.onclick=()=>openContractForEnrollment(b.dataset.recordContract));$$('[data-record-print]').forEach(b=>b.onclick=()=>printContractById(b.dataset.recordPrint));$('[data-record-link-guardian]')?.addEventListener('click',async()=>{const guardianId=$('#record-guardian-select')?.value;if(!guardianId)return toast('Selecione um responsável.','warning');try{await one.save('one_student_guardians',{student_id:state.activeRecordStudentId,guardian_id:guardianId,relationship:$('#record-guardian-relationship').value,is_legal:false,is_financial:false,is_primary:false,is_emergency:false});toast('Responsável vinculado.');await refreshAll()}catch(e){toast(e.message,'error')}});$$('[data-record-unlink-guardian]').forEach(b=>b.onclick=async()=>{if(!confirm('Desvincular este responsável do aluno?'))return;try{await one.remove('one_student_guardians',b.dataset.recordUnlinkGuardian);toast('Vínculo removido.');await refreshAll()}catch(e){toast(e.message,'error')}});$$('[data-record-toggle-financial]').forEach(b=>b.onclick=async()=>{const link=state.studentGuardians.find(x=>x.id===b.dataset.recordToggleFinancial);if(!link)return;try{await one.save('one_student_guardians',{is_financial:!link.is_financial},link.id);toast('Responsável financeiro atualizado.');await refreshAll()}catch(e){toast(e.message,'error')}})}
init();
